-- Script callbacks: define these as globals in your .lua script and the
-- engine will call them (all optional).
---@type fun()
--- Called when an enabled script instance is being loaded.
Awake = nil
---@type fun()
--- Called on the frame when a script is enabled before any `Update` methods are called the first time.
Start = nil
---@type fun()
--- Called when the script is destroyed.
OnDestroy = nil
---@type fun()
--- Called every frame if enabled.
Update = nil
---@type fun()
--- Called for physics calculations.
FixedUpdate = nil
---@type fun()
--- Called every frame if enabled.
LateUpdate = nil
---@type fun()
--- Called when the object becomes enabled and active.
OnEnable = nil
---@type fun()
--- Called when the script becomes disabled.
OnDisable = nil
---@type fun()
--- Called before the application quits.
OnApplicationQuit = nil
---@type fun(pause: boolean)
--- Called when the application pauses or resumes on losing or regaining focus.
OnApplicationPause = nil
---@type fun(focus: boolean)
--- Called when the player gets or loses focus.
OnApplicationFocus = nil
---@type fun(collision: any)
--- Called when this collider/rigidbody starts touching another rigidbody/collider.
OnCollisionEnter = nil
---@type fun(collision: any)
--- Called when this collider/rigidbody stops touching another rigidbody/collider.
OnCollisionExit = nil
---@type fun(collision: any)
--- Called once per frame for every collider or rigidbody touching another collider or rigidbody.
OnCollisionStay = nil
---@type fun(collision: any)
--- Called when an incoming collider makes contact with this object's collider (2D physics only).
OnCollisionEnter2D = nil
---@type fun(collision: any)
--- Called when a collider on another object stops touching this object's collider (2D physics only).
OnCollisionExit2D = nil
---@type fun(collision: any)
--- Called each frame where a collider on another object is touching this object's collider (2D physics only).
OnCollisionStay2D = nil
---@type fun(other: any)
--- Called when a GameObject collides with another GameObject.
OnTriggerEnter = nil
---@type fun(other: any)
--- Called when the collider other stops touching the trigger.
OnTriggerExit = nil
---@type fun(other: any)
--- Called once per physics update for every collider other that is touching the trigger.
OnTriggerStay = nil
---@type fun(other: any)
--- Called when another object enters a trigger collider attached to this object (2D physics only).
OnTriggerEnter2D = nil
---@type fun(other: any)
--- Called when another object leaves a trigger collider attached to this object (2D physics only).
OnTriggerExit2D = nil
---@type fun(other: any)
--- Called each frame where another object is within a trigger collider attached to this object (2D physics only).
OnTriggerStay2D = nil
---@type fun(controller: any)
OnControllerColliderHit = nil
---@type fun(force: number)
--- Called when a joint attached to the same game object breaks.
OnJointBreak = nil
---@type fun(force: number)
--- Called when a `Joint2D` attached to the same game object breaks.
OnJointBreak2D = nil
---@type fun()
--- Called when the CanvasGroup changes.
OnCanvasGroupChanged = nil
---@type fun()
--- Called when the RectTransform is removed.
OnRectTransformRemoved = nil
---@type fun()
--- Called when the dimensions of the RectTransform change.
OnRectTransformDimensionsChange = nil
---@type fun()
--- Called when the list of children of the transform changes.
OnTransformChildrenChanged = nil
---@type fun()
--- Called when a direct or indirect parent of the transform changes.
OnTransformParentChanged = nil
---@type fun()
--- Called before the transform's parent changes.
OnBeforeTransformParentChanged = nil
---@type fun()
--- Called when the user presses the mouse button while over the Collider.
OnMouseDown = nil
---@type fun()
--- Called when the mouse enters the Collider.
OnMouseEnter = nil
---@type fun()
--- Called when the user clicks on a Collider and is still holding down the mouse.
OnMouseDrag = nil
---@type fun()
--- Called when the mouse is no longer over the Collider.
OnMouseExit = nil
---@type fun()
--- Called every frame while the mouse is over the Collider.
OnMouseOver = nil
---@type fun()
--- Called when the user releases the mouse button.
OnMouseUp = nil
---@type fun()
--- Called when the mouse is released over the same Collider as it was pressed.
OnMouseUpAsButton = nil
---@type fun()
--- Called on an `Animator` move.
OnAnimatorMove = nil
---@type fun()
--- Called for setting up animation IK (inverse kinematics).
OnAnimatorIK = nil
---@type fun()
--- Called after a camera has finished rendering, allows modifying the Camera's final image.
OnRenderImage = nil
---@type fun()
--- Called after a camera has finished rendering the scene.
OnPostRender = nil
---@type fun()
--- Called before a camera culls the scene.
OnPreCull = nil
---@type fun()
--- Called before a camera renders the scene.
OnPreRender = nil
---@type fun()
--- Called after the camera has rendered the scene.
OnRenderObject = nil
---@type fun()
--- Called for each camera if the object is visible and not a UI element.
OnWillRenderObject = nil
---@type fun()
--- Called when the renderer becomes visible by any camera.
OnBecameVisible = nil
---@type fun()
--- Called when the renderer is no longer visible by any camera.
OnBecameInvisible = nil
---@type fun(other: any)
--- Called when a particle hits a Collider.
OnParticleCollision = nil
---@type fun(other: any)
--- Called when all particles in the system have died, and no new particles will be born.
OnParticleSystemStopped = nil
---@type fun()
--- Called when any particles in a Particle System meet the conditions in the trigger module.
OnParticleTrigger = nil
---@type fun()
--- Called when a Particle System's built-in update job has been scheduled.
OnParticleUpdateJobScheduled = nil
---@type fun(player: Player)
--- Called when a remote Player joins the instance.
OnPlayerJoined = nil
---@type fun(player: Player)
--- Called when a remote Player leaves the instance.
OnPlayerLeft = nil
---@type fun()
--- Called you connect to an online instance.
OnInstanceConnected = nil
---@type fun()
--- Called you disconnect from an online instance.
OnInstanceDisconnected = nil
---@type fun()
--- Called you lost connection to an online instance.
OnInstanceConnectionLost = nil
---@type fun()
--- Called you recover connection to the online instance.
OnInstanceConnectionRecovered = nil
---@type fun(avatar: Avatar, player: Player)
--- Called when a local player's Avatar Loads.
OnLocalPlayerAvatarLoaded = nil
---@type fun(avatar: Avatar, player: Player)
--- Called when a local player's Avatar Clears.
OnLocalPlayerAvatarClear = nil
---@type fun(avatar: Avatar, player: Player)
--- Called when a remote player's Avatar Loads.
OnRemotePlayerAvatarLoaded = nil
---@type fun(avatar: Avatar, player: Player)
--- Called when a remote player's Avatar Clears.
OnRemotePlayerAvatarClear = nil
---@type fun(spawnable: Spawnable, spawner: Player)
--- Called when a spawnable is spawned.
OnSpawnableCreated = nil
---@type fun(spawnable: Spawnable, spawner: Player)
--- Called when a spawnable is deleted.
OnSpawnableDestroyed = nil
---@type fun(switchingToXr: boolean)
--- Called the frame before initializing XR loaders. The switch can still fail.
OnPreVRModeSwitch = nil
---@type fun(switchedToXr: boolean)
--- Called the frame after initializing XR loaders. This means the switch was successful.
OnPostVRModeSwitch = nil
---@type fun(switchingToXr: boolean)
--- Called the frame after the switch failed. This means the switch has failed.
OnFailedVRModeSwitch = nil
---@type fun()
--- Same as *FixedUpdate()*, but runs after all other *FixedUpdate()* Unity Events on the execution order.
OnPostFixedUpdate = nil
---@type fun()
--- Same as *OnPostUpdate()*, but runs after all other *OnPostUpdate()* Unity Events on the execution order.
OnPostUpdate = nil
---@type fun()
--- Same as *OnPostLateUpdate()*, but runs after all other *OnPostLateUpdate()* Unity Events on the execution order.
OnPostLateUpdate = nil

-- Storage persistence API (docs/cck/lua/api/storage.md)

---@class StorageBin
---@field HasData boolean Whether this bin has Data or not. It will be true a file was found and loaded successfully.
---@field SizeAllowed integer How many bytes are allowed for this storage bin, in total. Does not include data outside of your control that we add during the serialization process, such as encryption stuff, headers, section data, etc.
---@field CurrentSize integer Current reported size of this storage bin, in bytes. Does not include data outside of your control that we add during the serialization process, such as encryption stuff, headers, section data, etc.
---@field Path string Path of the file on disk.
---@field GetBoolean fun(key: string): boolean|nil Get the value of a key as a `boolean`, or `nil` if the key is `nil` or not present.
---@field GetNumber fun(key: string): number|nil Get the value of a key as a `number`, or `nil` if the key is `nil` or missing.
---@field GetString fun(key: string): string|nil Get the value of a key as a `string`, or `nil` if the key is `nil` or missing.
---@field GetTable fun(key: string): table|nil Get the value of a key as a `table`, or `nil` if the key is `nil` or missing.
---@field HasValue fun(key: string): boolean Determine if the given named `key` is present in the underlying `table`.
---@field SetBoolean fun(key: string, value: boolean|nil) Set the value of a key to a `boolean` or `nil`. You will need to call `Save()` to commit this change to disk.
---@field SetNumber fun(key: string, value: number|nil) Set the value of a key to a `number` or `nil`. You will need to call `Save()` to commit this change to disk.
---@field SetString fun(key: string, value: string|nil) Set the value of a key to a `string` or `nil`. You will need to call `Save()` to commit this change to disk.
---@field SetTable fun(key: string, value: table|nil) Set the value of a key to a `table` or `nil`. **IMPORTANT:** Any values in the provided table or subtables that are not `nil`, `number`, `boolean`, `table`, or `string` will be silently stripped during serialization! You will need to call `Save()` to commit this change to disk.

---@class StorageBinReadonly
---@field HasData boolean Whether this bin has Data or not. It will be true a file was found and loaded successfully.
---@field GetBoolean fun(key: string): boolean|nil Get the value of a key as a `boolean`, or `nil` if the key is `nil` or not present.
---@field GetNumber fun(key: string): number|nil Get the value of a key as a `number`, or `nil` if the key is `nil` or missing.
---@field GetString fun(key: string): string|nil Get the value of a key as a `string`, or `nil` if the key is `nil` or missing.
---@field GetTable fun(key: string): table|nil Get the value of a key as a `table`, or `nil` if the key is `nil` or missing.
---@field HasValue fun(key: string): boolean Determine if the given named `key` is present in the underlying `table`.

---@class Storage
---@field Public StorageBin Access to the Public Bin.
---@field Private StorageBin Access to the Private Bin.
---@field GetPublicStorage fun(contentType: any, assetGuid: any): StorageBinReadonly|nil Access to other content's Public Bins locked to read only mode.

